/** @type {import('next').NextConfig} */
const nextConfig = {
  reactStrictMode: true,
};

module.exports = nextConfig;

import { randomUUID } from "crypto";
import { mkdir, readFile, writeFile } from "fs/promises";
import path from "path";

const dataDir = path.join(process.cwd(), "data");
const dataFile = path.join(dataDir, "books.json");

export async function getBooks() {
  try {
    const raw = await readFile(dataFile, "utf8");
    const books = JSON.parse(raw);
    if (!Array.isArray(books)) return [];
    return books;
  } catch (error) {
    if (error && error.code === "ENOENT") return [];
    throw error;
  }
}

export async function getBook(id) {
  const books = await getBooks();
  return books.find((book) => book.id === id) || null;
}

async function saveBooks(books) {
  await mkdir(dataDir, { recursive: true });
  await writeFile(dataFile, JSON.stringify(books, null, 2) + "\n", "utf8");
}

export async function addBook({ title, author, notes }) {
  const trimmedTitle = String(title || "").trim();
  const trimmedAuthor = String(author || "").trim();
  const trimmedNotes = String(notes || "").trim();

  if (!trimmedTitle || !trimmedAuthor) {
    throw new Error("Title and author are required.");
  }

  const books = await getBooks();
  const book = {
    id: randomUUID(),
    title: trimmedTitle,
    author: trimmedAuthor,
    notes: trimmedNotes,
    status: "reading",
    createdAt: new Date().toISOString(),
  };

  books.unshift(book);
  await saveBooks(books);
  return book;
}

export async function finishBook(id) {
  const books = await getBooks();
  const book = books.find((item) => item.id === id);
  if (!book) return null;
  if (book.status !== "finished") {
    book.status = "finished";
    book.finishedAt = new Date().toISOString();
    await saveBooks(books);
  }
  return book;
}

