:root {
  color-scheme: light;
  --ink: #1c1917;
  --muted: #57534e;
  --line: #e7e5e4;
  --paper: #fafaf9;
  --card: #ffffff;
  --accent: #9a3412;
  --accent-soft: #ffedd5;
