.section h2 {
  margin: 0 0 12px;
  font-size: 1.15rem;
  letter-spacing: 0.02em;
}

.list {
  list-style: none;
  margin: 0;
  padding: 0;
  border-top: 1px solid var(--line);
}

.book {
  display: flex;
  gap: 16px;
  justify-content: space-between;
  align-items: center;
  padding: 14px 0;
  border-bottom: 1px solid var(--line);
}

.book a {
  text-decoration: none;
}

.book a:hover .title {
  text-decoration: underline;
}

.title {
  font-size: 1.1rem;
}

.author {
  color: var(--muted);
  font-size: 0.95rem;
}

button,
.button {
  appearance: none;
  border: 1px solid var(--line);
  background: var(--card);
  color: var(--ink);
  font: inherit;
  font-size: 0.9rem;
  padding: 8px 12px;
  border-radius: 6px;
  cursor: pointer;
  text-decoration: none;
}

button:hover,
.button:hover {
  background: var(--accent-soft);
}

form {
  display: grid;
  gap: 12px;
  margin-top: 12px;
}

label {
  display: grid;
  gap: 4px;
  font-size: 0.9rem;
}

input,
textarea {
  font: inherit;
  padding: 8px 10px;
  border: 1px solid var(--line);
  border-radius: 6px;
  background: var(--card);
  color: var(--ink);
}

textarea {
  min-height: 120px;
  resize: vertical;
}

.notes {
  white-space: pre-wrap;
  margin-top: 20px;
}

.back {
  display: inline-block;
  margin-bottom: 20px;
  color: var(--muted);
}

.error {
  color: #b91c1c;
  margin: 0;
}

