import Link from "next/link";
import { createBook, markFinished } from "./actions";
import { getBooks } from "../lib/books";

export const dynamic = "force-dynamic";

function BookRow({ book, showFinish }) {
  return (
    <li className="book">
      <div>
        <Link href={`/books/${book.id}`}>
          <div className="title">{book.title}</div>
          <div className="author">{book.author}</div>
        </Link>
      </div>
      {showFinish ? (
        <form action={markFinished}>
          <input type="hidden" name="id" value={book.id} />
          <button type="submit">Mark finished</button>
        </form>
      ) : null}
    </li>
  );
}

export default async function HomePage() {
  const books = await getBooks();
  const reading = books.filter((book) => book.status !== "finished");
  const finished = books.filter((book) => book.status === "finished");

  return (
    <>
      <header>
        <h1>Reading list</h1>
        <p>What I'm reading now, and what I've already finished.</p>
      </header>

      <section className="section">
        <h2>Currently reading</h2>
        {reading.length === 0 ? (
          <p className="empty">Nothing in progress.</p>
        ) : (
          <ul className="list">
            {reading.map((book) => (
              <BookRow key={book.id} book={book} showFinish />
            ))}
          </ul>
        )}
      </section>

      <section className="section">
        <h2>Finished</h2>
        {finished.length === 0 ? (
          <p className="empty">No finished books yet.</p>
        ) : (
          <ul className="list">
            {finished.map((book) => (
              <BookRow key={book.id} book={book} />
            ))}
          </ul>
        )}
      </section>

      <section className="section">
        <h2>Add a book</h2>
        <form action={createBook}>
          <label>
            Title
            <input name="title" required placeholder="The Left Hand of Darkness" />
          </label>
          <label>
            Author
            <input name="author" required placeholder="Ursula K. Le Guin" />
          </label>
          <label>
            Notes
            <textarea name="notes" placeholder="Why I picked it up, quotes, thoughts..." />
          </label>
          <div>
            <button type="submit">Add book</button>
          </div>
        </form>
      </section>
    </>
  );
}

