import Link from "next/link";
import { notFound } from "next/navigation";
import { markFinished } from "../../actions";
import { getBook } from "../../../lib/books";

export const dynamic = "force-dynamic";

export async function generateMetadata({ params }) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) return { title: "Book not found" };
  return {
    title: `${book.title} — Reading list`,
    description: `${book.title} by ${book.author}`,
  };
}

export default async function BookPage({ params }) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) notFound();

  return (
    <>
      <Link className="back" href="/">
        ← All books
      </Link>
      <header>
        <h1>{book.title}</h1>
        <p className="meta">
          {book.author}
          {" · "}
          {book.status === "finished" ? "Finished" : "Currently reading"}
        </p>
      </header>

      {book.status !== "finished" ? (
        <form action={markFinished}>
          <input type="hidden" name="id" value={book.id} />
          <button type="submit">Mark finished</button>
        </form>
      ) : null}

      <section className="section">
        <h2>Notes</h2>
        {book.notes ? (
          <p className="notes">{book.notes}</p>
        ) : (
          <p className="empty">No notes yet.</p>
        )}
      </section>
    </>
  );
}

