"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { addBook, finishBook } from "../lib/books";

export async function createBook(formData) {
  const book = await addBook({
    title: formData.get("title"),
    author: formData.get("author"),
    notes: formData.get("notes"),
  });

  revalidatePath("/");
  redirect(`/books/${book.id}`);
}

export async function markFinished(formData) {
  const id = String(formData.get("id") || "");
  const book = await finishBook(id);
  if (!book) return;

  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}

import Link from "next/link";
import { createBook, markFinished } from "./actions";
import { getBooks } from "../lib/books";

export const dynamic = "force-dynamic";

function BookRow({ book, showFinish }) {
  return (
    <li className="book">
      <div>
        <Link href={`/books/${book.id}`}>
          <div className="title">{book.title}</div>
          <div className="author">{book.author}</div>
        </Link>
      </div>
      {showFinish ? (
        <form action={markFinished}>
          <input type="hidden" name="id" value={book.id} />
          <button type="submit">Mark finished</button>
        </form>
      ) : null}
    </li>
  );
}

export default async function HomePage() {
  const books = await getBooks();
  const reading = books.filter((book) => book.status !== "finished");
  const finished = books.filter((book) => book.status === "finished");

  return (
    <>
      <header>
        <h1>Reading list</h1>
        <p>What I'm reading now, and what I've already finished.</p>
      </header>

      <section className="section">
        <h2>Currently reading</h2>
        {reading.length === 0 ? (
          <p className="empty">Nothing in progress.</p>
        ) : (
          <ul className="list">
            {reading.map((book) => (
              <BookRow key={book.id} book={book} showFinish />
            ))}
          </ul>
        )}
      </section>

      <section className="section">
        <h2>Finished</h2>
        {finished.length === 0 ? (
          <p className="empty">No finished books yet.</p>
        ) : (
          <ul className="list">
            {finished.map((book) => (
              <BookRow key={book.id} book={book} />
            ))}
          </ul>
        )}
      </section>

      <section className="section">
        <h2>Add a book</h2>
        <form action={createBook}>
          <label>
            Title
            <input name="title" required placeholder="The Left Hand of Darkness" />
          </label>
          <label>
            Author
            <input name="author" required placeholder="Ursula K. Le Guin" />
          </label>
          <label>
            Notes
            <textarea name="notes" placeholder="Why I picked it up, quotes, thoughts..." />
          </label>
          <div>
            <button type="submit">Add book</button>
          </div>
        </form>
      </section>
    </>
  );
}

import Link from "next/link";
import { notFound } from "next/navigation";
import { markFinished } from "../../actions";
import { getBook } from "../../../lib/books";

export const dynamic = "force-dynamic";

export async function generateMetadata({ params }) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) return { title: "Book not found" };
  return {
    title: `${book.title} — Reading list`,
    description: `${book.title} by ${book.author}`,
  };
}

export default async function BookPage({ params }) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) notFound();

  return (
    <>
      <Link className="back" href="/">
        ← All books
      </Link>
      <header>
        <h1>{book.title}</h1>
        <p className="meta">
          {book.author}
          {" · "}
          {book.status === "finished" ? "Finished" : "Currently reading"}
        </p>
      </header>

      {book.status !== "finished" ? (
        <form action={markFinished}>
          <input type="hidden" name="id" value={book.id} />
          <button type="submit">Mark finished</button>
        </form>
      ) : null}

      <section className="section">
        <h2>Notes</h2>
        {book.notes ? (
          <p className="notes">{book.notes}</p>
        ) : (
          <p className="empty">No notes yet.</p>
        )}
      </section>
    </>
  );
}

